select lc.*,lt.name as type_name from law_case lc left join law_type lt on lc.type_id = lt.id


        and title like concat('%',#{title},'%')


        and type_id = #{typeId}


        and tags like concat('%',#{tags},'%')


        and status = #{status}

order by lc.publish_time desc
